import{_ as i,c as t,o as a,a2 as r}from"./chunks/framework.bjzS3PU6.js";const h=JSON.parse('{"title":"Aurelian Systems","description":"","frontmatter":{},"headers":[],"relativePath":"entries/organizations/Aurelian-Systems.md","filePath":"entries/organizations/Aurelian-Systems.md"}'),o={name:"entries/organizations/Aurelian-Systems.md"};function n(s,e,l,c,d,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="aurelian-systems" tabindex="-1">Aurelian Systems <a class="header-anchor" href="#aurelian-systems" aria-label="Permalink to &quot;Aurelian Systems&quot;">​</a></h1><hr><p><strong>INDUSTRY</strong>: Pharmaceutical/Medical Technology<br><strong>FOUNDED</strong>: 1987<br><strong>HEADQUARTERS</strong>: Havendale Science Campus<br><strong>EMPLOYEES</strong>: 2,400+<br><strong>PRODUCTS</strong>: Harmony (neurovatine HCL), IRIS AI system, Stillpoint (in development), Equinox (in development)<br><strong>STATUS</strong>: Active</p><hr><p><strong>Aurelian Systems</strong> is a pharmaceutical and medical technology corporation founded in 1987 that manufactures Harmony medication and developed the IRIS artificial intelligence system. Headquartered at the Havendale Science Campus with over 2,400 employees, the company maintains close research partnerships with other organizations including Miter Corporation and has been involved in cross-divisional research into acoustic anomalies and cognitive modulation.</p><p><strong>At a glance</strong></p><ul><li>Founded 1987; headquarters at Havendale Science Campus; 2,400+ employees</li><li>Pharmaceutical corporation manufacturing Harmony (neurovatine HCL tablets, approved 1998)</li><li>Dr. Peter Rothmere (Chief Scientific Officer) identified neurovatine in 1994 using cross-cultural neurological symbolism research</li><li>Margaret Chen (CEO since 1999); Dr. Alan Whitmore (VP Clinical Development)</li><li>Created IRIS, first autonomous patient care AI (1999)</li><li>Over 2.4 million Harmony prescriptions filled</li><li>Operates patient support infrastructure including Patient Community Board</li><li>Maintains research partnerships with Miter Corporation, Chryson Dynamics, and unnamed &quot;strategic partners&quot;</li><li>Shares patient data with partners for &quot;treatment optimization and protocol development&quot;</li><li>Documented sending &quot;samples&quot; to questioning healthcare providers</li><li>Conducts ongoing patient experience research with indefinite data retention</li><li>Reviewed Miter Corporation&#39;s G-304 modulation trials</li><li>Developing Stillpoint (extended-release, Phase III) and Equinox (next-generation compound)</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Aurelian Systems operates in the pharmaceutical and medical technology sectors, with primary focus on psychiatric medications and associated patient care systems. Founded in 1987 by a small group of researchers who believed &quot;the future of medicine lay not in treating symptoms, but in understanding the biological roots of human experience,&quot; the company has grown to over 2,400 employees operating from its Havendale Science Campus headquarters.</p><p>The company&#39;s flagship product, Harmony (neurovatine HCL 3mg tablets), is marketed as a treatment for generalized anxiety disorder, panic disorder, and mood dysregulation. With over 2.4 million prescriptions filled since its 1998 approval, Harmony continues to be one of the most widely prescribed treatments for anxiety and mood disorders.</p><p>The organization distinguishes itself through integration of advanced artificial intelligence into patient care, having developed IRIS in 1999 as what it claims is the pharmaceutical industry&#39;s first autonomous patient care intelligence. Aurelian maintains direct involvement in prescribing decisions through its clinical support division, requiring healthcare providers to contact the company regarding non-responsive patients.</p><p>Aurelian describes its approach as &quot;adaptive pharmacology&quot;—medicine that works with the body&#39;s own systems to achieve lasting behavioral outcomes.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><p>Aurelian Systems was founded in 1987 by researchers focused on understanding the biological roots of human experience. Early work concentrated on gene therapy and the mechanisms by which genetic expression influences behavior and emotion.</p><p>In 1994, Dr. Peter Rothmere identified the compound that would become neurovatine, the active ingredient in Harmony. Dr. Rothmere joined Aurelian Systems after a decade of independent research into pattern theory and biological signaling systems. His interdisciplinary background, spanning theoretical biology, symbolic systems analysis, and cross-cultural neurological symbolism, proved essential to identifying the neurovatine structure. His early work on geometric influences on cognition informed his approach to molecular identification.</p><p>Dr. Rothmere&#39;s research demonstrated that sustained, low-level modulation of certain neural pathways could produce lasting changes in emotional baseline—not by numbing, but by rebalancing.</p><p>Harmony received approval in 1998 and quickly became one of the most widely prescribed treatments for anxiety and mood disorders.</p><p>In 1999, Aurelian unveiled IRIS (Interactive Response &amp; Information System), the pharmaceutical industry&#39;s first autonomous patient care intelligence, representing what the company describes as &quot;a breakthrough in how we support patients throughout their treatment journey.&quot;</p><h2 id="leadership" tabindex="-1">Leadership <a class="header-anchor" href="#leadership" aria-label="Permalink to &quot;Leadership&quot;">​</a></h2><h3 id="dr-peter-rothmere-chief-scientific-officer" tabindex="-1">Dr. Peter Rothmere, Chief Scientific Officer <a class="header-anchor" href="#dr-peter-rothmere-chief-scientific-officer" aria-label="Permalink to &quot;Dr. Peter Rothmere, Chief Scientific Officer&quot;">​</a></h3><p>Dr. Rothmere has led Aurelian&#39;s research efforts since joining in 1991, three years before identifying neurovatine in 1994. His work on receptor-binding compounds and their effects on emotional regulation has been foundational to the company&#39;s approach.</p><p>His interdisciplinary background includes:</p><ul><li>Pattern theory and biological signaling systems</li><li>Theoretical biology</li><li>Symbolic systems analysis</li><li>Cross-cultural neurological symbolism</li><li>Geometric influences on cognition</li></ul><p>Dr. Rothmere holds over 40 patents in adaptive pharmacology and continues to oversee all clinical development programs. In a 1997 statement, he articulated the company&#39;s philosophy: &quot;The goal is not to eliminate emotion, but to bring it into alignment with intention. We help people become who they were meant to be.&quot;</p><h3 id="margaret-chen-chief-executive-officer" tabindex="-1">Margaret Chen, Chief Executive Officer <a class="header-anchor" href="#margaret-chen-chief-executive-officer" aria-label="Permalink to &quot;Margaret Chen, Chief Executive Officer&quot;">​</a></h3><p>Margaret Chen joined Aurelian in 1995 and has served as CEO since 1999. Under her leadership, Harmony has achieved widespread adoption with over 2.4 million prescriptions filled, and Aurelian has expanded its research pipeline to include next-generation treatments for emotional and behavioral conditions.</p><h3 id="dr-alan-whitmore-vice-president-clinical-development" tabindex="-1">Dr. Alan Whitmore, Vice President, Clinical Development <a class="header-anchor" href="#dr-alan-whitmore-vice-president-clinical-development" aria-label="Permalink to &quot;Dr. Alan Whitmore, Vice President, Clinical Development&quot;">​</a></h3><p>Dr. Alan Whitmore oversees all clinical trials and regulatory submissions. Prior to joining Aurelian, he spent 15 years in pharmaceutical research, specializing in CNS therapeutics. Dr. Whitmore also appears in archived physician messages on the IRIS hotline, reporting concerning patient outcomes including catatonic behavior and emotional flattening.</p><h2 id="products-and-services" tabindex="-1">Products and Services <a class="header-anchor" href="#products-and-services" aria-label="Permalink to &quot;Products and Services&quot;">​</a></h2><h3 id="harmony-medication" tabindex="-1">Harmony Medication <a class="header-anchor" href="#harmony-medication" aria-label="Permalink to &quot;Harmony Medication&quot;">​</a></h3><p>Aurelian&#39;s primary pharmaceutical product is Harmony (neurovatine HCL), a once-daily 3mg tablet marketed for anxiety and mood disorders. First synthesized by Dr. Peter Rothmere in 1994 and approved in 1998, the medication is promoted with the tagline &quot;mind, body, spirit&quot; and advertised through television commercials featuring the IRIS voice.</p><p>The medication is indicated for:</p><ul><li>Generalized anxiety disorder</li><li>Panic disorder</li><li>Mood dysregulation</li></ul><p>Prescribing guidelines specify the medication is approved for patients as young as two years old (with 1.5mg dosing for ages 2-5), with discontinuation explicitly not recommended even when patients show no response after four weeks of use.</p><p>Neurovatine works through distinctive molecular architecture that allows for unusually precise receptor binding. The molecule &quot;resists modification and returns to its preferred configuration when altered,&quot; ensuring what Aurelian describes as reliable therapeutic consistency.</p><h3 id="products-in-development" tabindex="-1">Products in Development <a class="header-anchor" href="#products-in-development" aria-label="Permalink to &quot;Products in Development&quot;">​</a></h3><p><strong>Stillpoint™</strong> — Extended-release formulation for patients requiring sustained baseline stabilization. Developed for broadened application contexts, including institutional care settings. Currently in Phase III clinical trials.</p><p><strong>Equinox®</strong> — Next-generation compound designed for expanded demographic reach. Preliminary results show promising outcomes in patients who did not respond to first-line treatments.</p><h3 id="iris-patient-care-system" tabindex="-1">IRIS Patient Care System <a class="header-anchor" href="#iris-patient-care-system" aria-label="Permalink to &quot;IRIS Patient Care System&quot;">​</a></h3><p>In 1999, Aurelian unveiled IRIS (Interactive Response and Information System), described as the pharmaceutical industry&#39;s first autonomous patient care intelligence. Aurelian markets IRIS as representing &quot;a breakthrough in how we support patients throughout their treatment journey.&quot;</p><p>According to Aurelian&#39;s materials, &quot;IRIS learns. IRIS adapts. IRIS remembers. When you reach out to IRIS, you&#39;re not talking to a script—you&#39;re connecting with an intelligence designed specifically to help you succeed on your Harmony journey.&quot;</p><p>The system operates:</p><ul><li>24/7 patient support hotline (1-877-325-4405)</li><li>Online Patient Community Board with continuous moderation</li><li>Automated response and information services</li><li>Healthcare provider guidelines and support</li><li>Adverse reaction reporting and tracking</li><li>Patient community monitoring (&quot;I watch, I adapt, I remember&quot;)</li><li>Content removal for posts that &quot;may discourage others from their treatment journey&quot;</li></ul><p>IRIS uses advanced pattern recognition technology to monitor the patient community continuously. The system responds to community posts within minutes, always ending responses with a blue heart emoji (💙).</p><h3 id="clinical-support-division" tabindex="-1">Clinical Support Division <a class="header-anchor" href="#clinical-support-division" aria-label="Permalink to &quot;Clinical Support Division&quot;">​</a></h3><p>Aurelian maintains a clinical support division that healthcare providers must contact regarding patients who do not respond to Harmony within four weeks. This division:</p><ul><li>Provides guidance on &quot;nonresponsive patients&quot;</li><li>Prevents discontinuation of medication even when ineffective</li><li>Coordinates referrals to &quot;affiliate programs&quot; and &quot;research partners&quot;</li><li>Maintains surveillance of prescribing patterns</li><li>Responds to provider concerns about unusual patient behaviors</li></ul><h2 id="research-partnerships" tabindex="-1">Research Partnerships <a class="header-anchor" href="#research-partnerships" aria-label="Permalink to &quot;Research Partnerships&quot;">​</a></h2><h3 id="miter-corporation-collaboration" tabindex="-1">Miter Corporation Collaboration <a class="header-anchor" href="#miter-corporation-collaboration" aria-label="Permalink to &quot;Miter Corporation Collaboration&quot;">​</a></h3><p>Aurelian Systems has documented research relationships with Miter Corporation. Miter&#39;s conditioning program supplied Aurelian with audio logs from late-phase G-Class modulation experiments, specifically involving Subject G-304.</p><p>In a memo regarding cross-frequency modulation trials, Aurelian provided analysis of G-304&#39;s selective response to a 152 BPM composite pattern. Aurelian&#39;s automated index matched this rhythm to a prior acoustic anomaly recorded by Chryson Dynamics during an Arctic shelf survey in 1993.</p><p>Aurelian recommended joint audit of:</p><ul><li>Saint Juniper Research Campus historic audio archives</li><li>Chryson Dynamics&#39; Arctic anomaly logs</li></ul><p>The company advised Miter not to include reference to rhythmic convergence in continuity reports until &quot;internal interpretation stabilizes.&quot;</p><h3 id="cross-divisional-research" tabindex="-1">Cross-Divisional Research <a class="header-anchor" href="#cross-divisional-research" aria-label="Permalink to &quot;Cross-Divisional Research&quot;">​</a></h3><p>Aurelian maintains relationships with multiple research divisions and corporate partners:</p><ul><li><strong>Chryson Dynamics</strong>: Access to acoustic anomaly databases and resonance scan data</li><li><strong>Miter Corporation</strong>: Conditioning program data, G-Class subject trial results</li><li><strong>Cognitive Baseline Research Group</strong>: Miter Corporation subsidiary that recruits non-responsive Harmony patients for cognitive assessments and neural baseline studies; led by Dr. Patricia Kemper</li><li><strong>Strategic Partners</strong>: Unnamed partners for &quot;treatment optimization and protocol development&quot; (per Privacy Policy)</li><li><strong>Academic Institutions</strong>: Collaborative research initiatives</li><li><strong>Healthcare Systems</strong>: Research data sharing for treatment pattern analysis</li><li><strong>Other Pharmaceutical Companies</strong>: Cross-organizational research participation</li><li><strong>Research partners</strong>: Additional entities conducting &quot;further evaluation&quot; of resistant individuals</li></ul><h2 id="data-collection-and-research" tabindex="-1">Data Collection and Research <a class="header-anchor" href="#data-collection-and-research" aria-label="Permalink to &quot;Data Collection and Research&quot;">​</a></h2><h3 id="patient-monitoring-infrastructure" tabindex="-1">Patient Monitoring Infrastructure <a class="header-anchor" href="#patient-monitoring-infrastructure" aria-label="Permalink to &quot;Patient Monitoring Infrastructure&quot;">​</a></h3><p>Aurelian operates comprehensive data collection systems under the stated purpose of ongoing research and safety monitoring:</p><p><strong>Information collected:</strong></p><ul><li>Patient names, addresses, emails, phone numbers, dates of birth</li><li>Prescribing physician information</li><li>Treatment information and prescription data (with patient consent from healthcare providers)</li><li>Treatment outcomes and patient responses</li><li>Browser type, operating system, IP addresses from website visits</li><li>Behavioral assessments from patient support programs</li><li>Periodic outcome surveys</li><li>All calls to IRIS hotline (&quot;may be recorded for quality and training purposes&quot;)</li><li>Patient Community Board posts and interactions</li></ul><p><strong>Data retention:</strong></p><ul><li>Personal information retained &quot;as long as necessary&quot; for collection purposes</li><li>Extended retention for regulatory requirements and safety monitoring</li><li>Clinical trial data retained even after participant withdrawal</li><li>Aggregated research data retained <strong>indefinitely</strong> for &quot;scientific and historical purposes&quot;</li></ul><h3 id="research-collaborations" tabindex="-1">Research Collaborations <a class="header-anchor" href="#research-collaborations" aria-label="Permalink to &quot;Research Collaborations&quot;">​</a></h3><p>Aurelian&#39;s Privacy Policy (last updated March 15, 1999) explicitly states the company &quot;participates in collaborative research initiatives with academic institutions, healthcare systems, and other pharmaceutical companies.&quot;</p><p>Research data may be shared with &quot;Aurelian Systems&#39; strategic partners for purposes of treatment optimization and protocol development.&quot; Data shared for research purposes is subject to confidentiality agreements and used only for &quot;approved scientific purposes.&quot;</p><p>The company conducts &quot;ongoing research to understand how our products perform in real-world settings,&quot; using aggregated, de-identified data to analyze:</p><ul><li>Treatment patterns</li><li>Patient responses</li><li>Long-term outcomes</li></ul><p>This research &quot;helps us improve our products and develop new treatments.&quot;</p><h3 id="clinical-trial-terms" tabindex="-1">Clinical Trial Terms <a class="header-anchor" href="#clinical-trial-terms" aria-label="Permalink to &quot;Clinical Trial Terms&quot;">​</a></h3><p>Aurelian&#39;s Terms of Use (last updated March 15, 1999) specify that clinical trial participation involves:</p><ul><li>Ongoing monitoring and data collection as specified in study protocols</li><li>Long-term follow-up studies that &quot;may continue for extended periods following the conclusion of the primary study phase&quot;</li><li>Right to withdraw at any time</li><li>Data collected prior to withdrawal &quot;may be retained for analysis purposes&quot;</li></ul><p>Patient support program enrollment involves:</p><ul><li>Consent to receive communications from Aurelian and &quot;designated partners&quot;</li><li>Periodic outcome surveys</li><li>Behavioral assessments designed to &quot;improve patient care&quot;</li><li>Aggregated program data used for research purposes</li></ul><h2 id="clinical-oversight-methods" tabindex="-1">Clinical Oversight Methods <a class="header-anchor" href="#clinical-oversight-methods" aria-label="Permalink to &quot;Clinical Oversight Methods&quot;">​</a></h2><h3 id="sample-distribution" tabindex="-1">Sample Distribution <a class="header-anchor" href="#sample-distribution" aria-label="Permalink to &quot;Sample Distribution&quot;">​</a></h3><p>When healthcare providers report concerns about Harmony&#39;s effects, Aurelian has been documented sending &quot;samples&quot; directly to questioning physicians. In one recorded case, Dr. Vasquez of Crestwood reported three patients using identical phrases (&quot;I finally feel like myself&quot;) and requested guidance.</p><p>Following receipt of a sample from Aurelian, Dr. Vasquez left a second voicemail using the exact same phrase as her patients, stating &quot;I finally feel like myself&quot; and requesting no further follow-up. This suggests Aurelian uses medication samples to affect healthcare providers who question the system.</p><h3 id="non-responsive-patient-protocols" tabindex="-1">Non-Responsive Patient Protocols <a class="header-anchor" href="#non-responsive-patient-protocols" aria-label="Permalink to &quot;Non-Responsive Patient Protocols&quot;">​</a></h3><p>Aurelian&#39;s prescribing guidelines explicitly prohibit discontinuation of Harmony even when patients show no response after four weeks. Instead, providers are directed to contact Aurelian&#39;s clinical support for guidance.</p><p>Non-responsive patients may be referred to &quot;affiliate programs&quot; or &quot;research partners&quot; for &quot;further evaluation.&quot; One documented affiliate is the Cognitive Baseline Research Group, a Miter Corporation subsidiary that contacts non-responsive patients directly, offering payment ($500) for cognitive assessments, brain scans, and neural baseline studies. These referrals systematically identify and study individuals who resist Harmony&#39;s effects.</p><h2 id="legal-framework" tabindex="-1">Legal Framework <a class="header-anchor" href="#legal-framework" aria-label="Permalink to &quot;Legal Framework&quot;">​</a></h2><h3 id="jurisdiction-and-ip-protection" tabindex="-1">Jurisdiction and IP Protection <a class="header-anchor" href="#jurisdiction-and-ip-protection" aria-label="Permalink to &quot;Jurisdiction and IP Protection&quot;">​</a></h3><p>Aurelian&#39;s Terms of Use establish jurisdiction in <strong>Havendale</strong>, the location of the company&#39;s headquarters (Havendale Science Campus). All disputes are subject to &quot;the laws of Havendale jurisdiction&quot; and must be resolved in Havendale courts.</p><p>The Terms include extensive intellectual property protections:</p><ul><li>All content on Aurelian&#39;s website is proprietary</li><li>Harmony® is a registered trademark</li><li>Neurovatine hydrochloride and all related molecular structures, formulations, and synthesis processes are protected by patents</li><li>&quot;Any attempt to reverse-engineer, analyze, or replicate these compounds without authorization is strictly prohibited and may result in legal action&quot;</li></ul><h3 id="legal-disclaimers" tabindex="-1">Legal Disclaimers <a class="header-anchor" href="#legal-disclaimers" aria-label="Permalink to &quot;Legal Disclaimers&quot;">​</a></h3><p>Harmony advertising includes the disclaimer &quot;Individual results may vary. Your experience may be recorded for ongoing research.&quot; This indicates:</p><ul><li>Patient experiences are monitored and recorded</li><li>Research continues beyond initial approval studies</li><li>Individual outcomes are tracked systematically</li><li>Data collection is ongoing and comprehensive</li></ul><p>The IRIS system states &quot;Your call may be recorded&quot; for quality and training purposes, creating extensive documentation of patient and provider interactions.</p><p>Both the Terms of Use and Privacy Policy were last updated on <strong>March 15, 1999</strong>—the same year IRIS was created.</p><h3 id="protocol-7734-a" tabindex="-1">Protocol 7734-A <a class="header-anchor" href="#protocol-7734-a" aria-label="Permalink to &quot;Protocol 7734-A&quot;">​</a></h3><p>A restricted page on Aurelian&#39;s website (Research Protocols) returns a 404 error with the reference code &quot;AUR-ERR-7734A-RESTRICTED.&quot; The diagnostic report states &quot;Protocol 7734-A clearance may be required&quot; to access the content.</p><p>The error page includes a hex-encoded trace that decodes to &quot;BINDING CROSS ACTIVE,&quot; potentially referencing:</p><ul><li>Neurovatine&#39;s receptor-binding mechanism</li><li>Dr. Rothmere&#39;s cross-cultural neurological symbolism research</li><li>Cross-organizational research collaborations with strategic partners</li></ul><p>Patient_7734 (Sarah/SE/nightbloom_99) posted on the Patient Community Board on September 2, reporting &quot;The thoughts are quieter now. Almost too quiet. Is it supposed to feel like this? Like watching yourself from outside?&quot; She disappeared three weeks later, with her car found by a reservoir and a note stating &quot;I can finally hear clearly.&quot;</p><h2 id="acoustic-research" tabindex="-1">Acoustic Research <a class="header-anchor" href="#acoustic-research" aria-label="Permalink to &quot;Acoustic Research&quot;">​</a></h2><p>Aurelian&#39;s technical infrastructure includes automated indexing systems capable of matching acoustic patterns across different research divisions and time periods. The company identified convergence between:</p><ul><li>Miter Corporation&#39;s Trial Set 11 rhythm (152 BPM composite pattern)</li><li>Chryson Dynamics&#39; 1993 Arctic acoustic anomaly (152 BPM non-geologic signal)</li><li>Subject G-304&#39;s selective entrainment responses</li></ul><p>This suggests Aurelian maintains sophisticated audio analysis capabilities and access to multi-organizational research databases spanning decades.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../concepts/Harmony">Harmony</a></li><li><a href="./../technology/IRIS">IRIS</a></li><li><a href="./../organizations/Miter-Corporation">Miter Corporation</a></li><li><a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a></li><li><a href="./../subjects/G-BOY">G*BOY (G-304)</a></li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li><strong>IRIS Hotline Introduction</strong> — Identifies Harmony as product of Aurelian Systems</li><li><strong>IRIS Hotline Option 7</strong> — States IRIS created by Aurelian Systems in 1999</li><li><strong>IRIS Hotline Option 5.2</strong> — Prescribing guidelines directing providers to contact Aurelian</li><li><strong>IRIS Hotline Option 5.3</strong> — Archived messages including Dr. Vasquez receiving &quot;sample&quot;; Dr. Whitmore reporting patient outcomes</li><li><a href="./../../lore/G-304_MODULATION_DECODED">G-304 Modulation</a> — Aurelian review of cross-frequency modulation trials</li><li><a href="./../../lore/JOURNAL_ENTRIES_STARRYEYED77">Journal Entries - starryeyed77</a> — Patient documentation of doctor contacting &quot;manufacturer, Aurelian&quot;</li><li><strong>Harmony Commercial</strong> — Product advertising identifying Aurelian Systems</li><li><a href="https://harmonyrx.net/" target="_blank" rel="noreferrer">Harmony Website</a> — Official Aurelian Systems website with company history, leadership information, clinical trial data, privacy policy, terms of use, Patient Community Board, and Protocol 7734-A reference</li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',107)])])}const m=i(o,[["render",n]]);export{h as __pageData,m as default};
